mapper.select:
select * from orders


        and number like concat('%',#{dto.number},'%')


        and phone like concat('%',#{dto.phone},'%')


        and user_id = #{dto.userId}


        and status = #{dto.status}


        and order_time >= #{dto.beginTime}


        and order_time <= #{dto.endTime}


order by order_time desc

select count(id) from orders


        and order_time >= #{begin}


        and order_time < #{end}


        and status = #{status}

select sum(amount) from orders


        and order_time >= #{begin}


        and order_time < #{end}


        and status = #{status}

select date_format(order_time, '%Y-%m-%d') as date, sum(amount) as amount from orders where status = 5
and order_time >= #{begin}
and order_time < #{end}
group by date_format(order_time, '%Y-%m-%d') order by date

select od.name, sum(od.number) number from order_detail od, orders o where od.order_id = o.id and o.status = 5
and o.order_time >= #{begin}
and o.order_time < #{end}
group by od.name order by number desc limit 0,10
